# Splits Nav into a server wrapper (checks vendor session) and a client
# component (all existing search/mobile-menu interactivity, now vendor-aware).

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\Nav.tsx"), $bytes)
Write-Host "WRITTEN: src\components\Nav.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\NavClient.tsx"), $bytes)
Write-Host "WRITTEN: src\components\NavClient.tsx" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan